import{jumpTuning}from'./jump-tuning.js';
import{bodyDistanceInterval,bodyTouchesBeam,circlesTouchBody,containBody,separateBodyFromCircle}from'./creature-contact.js';
import{elementalAttack,segmentHit}from'./elemental-attacks.js';
export const BOSS={x:0,z:-5,radius:2.25,height:11.8};
export const ARENA={x:0,z:3,radius:11};
const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
export const guardianPhase=b=>b.bossHp>60?1:b.bossHp>30?2:3;
export const guardianDefeated=b=>b?.version===2?b.phase==='victory'&&b.bossHp===0&&b.finishStep===3:b?.round===3;
function shuffle(list,random){const a=list.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function randomFor(seed){let n=2166136261;for(const c of String(seed))n=Math.imul(n^c.charCodeAt(0),16777619);return()=>{n+=0x6D2B79F5;let t=Math.imul(n^n>>>15,1|n);t^=t+Math.imul(t^t>>>7,61|t);return((t^t>>>14)>>>0)/4294967296;};}
// Checked unit items only; no generated sentences or random distractor substitutions.
export function guardianSeals(unit,seed){const random=randomFor(seed),questions=shuffle((unit.questions||[]).filter(q=>q.prompt?.length<=115&&(q.options||[]).every(s=>s.length<=62)),random),gaps=shuffle((unit.gaps||[]).filter(q=>q.prompt?.length<=110&&(q.options||[]).every(s=>s.length<=62)),random),words=shuffle(unit.vocabulary||[],random);const candidates=[];
 for(const q of questions)if(q.prompt&&q.answer&&new Set(q.options||[]).size>=3)candidates.push({id:q.id,kind:'question',prompt:q.prompt,answer:q.answer,options:q.options});
 if(gaps.length){const g=gaps.find(q=>q.prompt&&q.answer&&new Set(q.options||[]).size>=3);if(g)candidates.splice(1,0,{id:g.id,kind:'completion',prompt:g.prompt,answer:g.answer,options:g.options});}
 const chosen=candidates.slice(0,3);for(const w of words){if(chosen.length===3)break;if(!w.en||!w.tr)continue;const others=shuffle([...new Set(words.map(x=>x.tr).filter(t=>t&&t!==w.tr))],random).slice(0,2);if(others.length===2)chosen.push({id:w.id,kind:'meaning',prompt:w.en,answer:w.tr,options:[w.tr,...others]});}
 if(chosen.length!==3)throw Error('The unit needs three checked finisher items.');
 return chosen.map(q=>{const wrong=shuffle([...new Set(q.options)].filter(x=>x!==q.answer),random).slice(0,2);return{...q,options:shuffle([q.answer,...wrong],random)};});
}
export function freshGuardian(unit,seed){return{version:2,hp:100,bossHp:100,round:0,phase:'intro',timer:0,attackNo:0,kind:'quake',targets:[],player:{x:0,z:5.8,y:0,vy:0},invulnerable:0,retries:0,finishStep:0,finishMistakes:0,seals:guardianSeals(unit,seed)};}
const finite=(v,a,b)=>Number.isFinite(v)&&v>=a&&v<=b;
export function validGuardian(b){return !!b&&b.version===2&&b.round===0&&finite(b.hp,1,100)&&finite(b.bossHp,0,100)&&['intro','windup','strike','recovery','finisher','victory'].includes(b.phase)&&finite(b.timer,0,20)&&Number.isInteger(b.attackNo)&&b.attackNo>=0&&b.attackNo<1000000&&['quake','beam','falls'].includes(b.kind)&&Array.isArray(b.targets)&&b.targets.length<=4&&b.targets.every(t=>finite(t.x,-20,20)&&finite(t.z,-15,20))&&b.player&&finite(b.player.x,-11,11)&&finite(b.player.z,-8,14)&&finite(b.player.y,0,5)&&finite(b.player.vy,-20,20)&&finite(b.invulnerable,0,3)&&Number.isInteger(b.retries)&&b.retries>=0&&Number.isInteger(b.finishStep)&&b.finishStep>=0&&b.finishStep<=3&&Number.isInteger(b.finishMistakes)&&b.finishMistakes>=0&&Array.isArray(b.seals)&&b.seals.length===3&&b.seals.every(q=>typeof q.id==='string'&&q.id.length<180&&['question','completion','meaning'].includes(q.kind)&&typeof q.prompt==='string'&&q.prompt.length<=1600&&typeof q.answer==='string'&&q.answer.length<=500&&Array.isArray(q.options)&&q.options.length===3&&new Set(q.options).size===3&&q.options.every(t=>typeof t==='string'&&t.length<=500)&&q.options.includes(q.answer))&&(b.phase==='victory'?b.finishStep===3&&b.bossHp===0:b.phase==='finisher'?b.bossHp===10-[0,3,6][b.finishStep]&&b.finishStep<3:b.bossHp>10&&b.finishStep===0);}
export function attackDuration(b,mode='relaxed'){const fast=mode==='challenge',phase=guardianPhase(b);return b.phase==='intro'?2.3:b.phase==='windup'?(fast?1.45:2.05)-(phase-1)*.13:b.phase==='strike'?(b.kind==='quake'?2.25:b.kind==='beam'?.85:.85):b.phase==='recovery'?(fast?2.8:3.6):99;}
export function quakeRadius(b){return b.timer*9;}
export function beamEnd(b){const t=b.targets[0]||b.player,dx=t.x-BOSS.x,dz=t.z-BOSS.z,d=Math.hypot(dx,dz)||1;return{x:BOSS.x+dx/d*23,z:BOSS.z+dz/d*23};}
export function inGuardianDanger(b,p=b.player,body={halfWidth:.35,halfDepth:.35}){if(b.phase!=='strike')return false;const yaw=Math.atan2(BOSS.x-p.x,BOSS.z-p.z);if(b.kind==='quake'){const d=bodyDistanceInterval(body,p,yaw,BOSS),r=quakeRadius(b);return p.y<.52&&d.max>r-.5&&d.min<r+.5;}if(b.kind==='beam')return b.timer>.12&&b.timer<.65&&bodyTouchesBeam(body,p,yaw,BOSS,beamEnd(b),.85);return b.timer>.34&&b.timer<.67&&b.targets.some(t=>circlesTouchBody(body,p,yaw,t,1.45));}
export class GuardianCombat{
 constructor(state,{mode='relaxed',partner='hufflepuff',bodyProfile={halfWidth:.35,halfDepth:.35},event=()=>{}}={}){this.state=state;this.bodyProfile=bodyProfile;this.mode=mode;this.partner=partner;this.event=event;this.shots=[];this.cast=null;this.cooldown=0;this.serial=0;this.active=true;}
 resume(){const b=this.state;if(['windup','strike','recovery'].includes(b.phase)){b.phase='windup';b.timer=0;this.target();}b.player.y=0;b.player.vy=0;b.invulnerable=1.2;this.shots=[];this.cast=null;}
 target(){const b=this.state,p=b.player;b.targets=b.kind==='falls'?[{x:p.x,z:p.z},{x:clamp(p.x+3.8,-7,7),z:p.z-1.5},{x:clamp(p.x-3.8,-7,7),z:p.z+1.5}]:[{x:p.x,z:p.z}];}
 nextAttack(){const b=this.state,patterns=guardianPhase(b)===1?['quake','beam']:guardianPhase(b)===2?['falls','quake','beam']:['beam','falls','quake','beam'];b.kind=patterns[b.attackNo%patterns.length];b.attackNo++;b.phase='windup';b.timer=0;this.target();this.event('warning',b.kind);}
 jump(){const b=this.state,p=b.player;if(!this.active||!['windup','strike','recovery'].includes(b.phase)||p.y>0||p.vy!==0)return false;p.vy=jumpTuning(this.bodyProfile?.level??0).guardianVelocity;this.event('jump');return true;}
 attack(){const b=this.state;if(!this.active||!['windup','strike','recovery'].includes(b.phase)||this.cast||this.cooldown>0)return false;const spec=elementalAttack(this.partner);this.cast={ranged:true,partner:this.partner,spec,element:spec.element,age:0,duration:spec.windup+spec.recovery,heading:Math.atan2(BOSS.x-b.player.x,BOSS.z-b.player.z),x:b.player.x,z:b.player.z};this.cooldown=this.cast.duration+.12;this.event('cast',this.cast);return true;}
 hitBoss(){const b=this.state;if(b.phase!=='recovery'){this.event('blocked');return false;}b.bossHp=Math.max(10,b.bossHp-10);this.event('boss-hit');if(b.bossHp===10){b.phase='finisher';b.timer=0;b.player.y=0;b.player.vy=0;this.cast=null;this.shots=[];this.event('finisher');}return true;}
 answer(text){const b=this.state;if(b.phase!=='finisher')return{accepted:false};const q=b.seals[b.finishStep];if(text!==q.answer){b.finishMistakes++;this.event('mistake');return{accepted:false,mistake:true,id:q.id};}b.finishStep++;b.bossHp=[10,7,4,0][b.finishStep];b.timer=0;this.event('seal',b.finishStep);if(b.finishStep===3){b.phase='victory';this.event('victory');}return{accepted:true,id:q.id,complete:b.finishStep===3};}
 hurt(){const b=this.state;if(b.invulnerable>0)return;b.hp=Math.max(0,b.hp-(this.mode==='challenge'?25:20));b.invulnerable=1.5;this.event('hurt');if(b.hp===0){b.hp=100;b.retries++;b.player={x:0,z:5.8,y:0,vy:0};b.phase='windup';b.timer=0;b.invulnerable=2;this.target();this.shots=[];this.cast=null;this.event('retry');}}
 step(dt,input={x:0,z:0}){if(!this.active||!Number.isFinite(dt)||dt<=0)return;dt=Math.min(.05,dt);const b=this.state,p=b.player;b.timer=Math.min(20,b.timer+dt);b.invulnerable=Math.max(0,b.invulnerable-dt);this.cooldown=Math.max(0,this.cooldown-dt);
 if(!['intro','finisher','victory'].includes(b.phase)){const length=Math.hypot(input.x,input.z),speed=this.mode==='relaxed'?4.9:5.1;if(length>0){p.x+=input.x/Math.max(1,length)*speed*dt;p.z+=input.z/Math.max(1,length)*speed*dt;}const yaw=Math.atan2(BOSS.x-p.x,BOSS.z-p.z);containBody(this.bodyProfile,p,yaw,ARENA);separateBodyFromCircle(this.bodyProfile,p,yaw,BOSS,BOSS.radius);
 if(p.y>0||p.vy>0){p.vy-=16*dt;p.y=Math.max(0,p.y+p.vy*dt);if(p.y===0){p.vy=0;this.event('land');}}if(inGuardianDanger(b,p,this.bodyProfile))this.hurt();
 if(b.timer>=attackDuration(b,this.mode)){if(b.phase==='intro'||b.phase==='recovery')this.nextAttack();else if(b.phase==='windup'){b.phase='strike';b.timer=0;this.event('strike',b.kind);}else{b.phase='recovery';b.timer=0;this.event('opening');}}}
 else if(b.phase==='intro'&&b.timer>=attackDuration(b,this.mode))this.nextAttack();
 if(this.cast){const a=this.cast,old=a.age;a.age+=dt;if(old<a.spec.windup&&a.age>=a.spec.windup){a.heading=Math.atan2(BOSS.x-p.x,BOSS.z-p.z);const y=Math.max(.7,p.y+.7);this.shots.push({id:'guardian-shot-'+(++this.serial),partner:this.partner,element:a.element,spec:a.spec,heading:a.heading,x:p.x,z:p.z,y,from:{x:p.x,z:p.z,y},travel:0,targetDistance:Math.hypot(p.x-BOSS.x,p.z-BOSS.z)});this.event('release',a);}if(a.age>=a.duration)this.cast=null;}
 this.shots=this.shots.filter(s=>{const prev={x:s.x,z:s.z},distance=s.spec.speed*dt;s.x+=Math.sin(s.heading)*distance;s.z+=Math.cos(s.heading)*distance;s.travel+=distance;s.y=s.from.y+(5.6-s.from.y)*clamp(s.travel/Math.max(.1,s.targetDistance-1.8),0,1);if(segmentHit(prev,s,BOSS,1.8)!==null){const hit=this.hitBoss();this.event('impact',{...s,hit});return false;}return s.travel<s.spec.range;});
 }
}
